        public Task<T?> YogasAsync<T>(ChartYogasParams parameters, RequestOptions? options = null, CancellationToken cancellationToken = default) =>
            _client.SendAsync<T>(Wire.NotNull(parameters, nameof(parameters)), options, cancellationToken);
    }
}
